-- SmartKhata Database Dump
-- Generated on 2026-02-23T07:31:26.559Z

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;

-- Table: schema_migrations
CREATE TABLE schema_migrations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  version INTEGER NOT NULL UNIQUE,
  name TEXT NOT NULL,
  applied_at TEXT NOT NULL DEFAULT (datetime('now')),
  checksum TEXT NOT NULL,
  execution_time_ms INTEGER NOT NULL
);


-- Table: products
CREATE TABLE products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  sku TEXT UNIQUE,
  barcode TEXT UNIQUE,
  sale_price INTEGER NOT NULL CHECK(sale_price >= 0),        -- In Paise
  purchase_price INTEGER CHECK(purchase_price >= 0),         -- In Paise
  gst_percent INTEGER NOT NULL DEFAULT 500 CHECK(gst_percent >= 0), -- Basis points (5.00% = 500)
  stock_qty INTEGER NOT NULL DEFAULT 0,
  low_stock_alert INTEGER,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, track_inventory INTEGER DEFAULT 1, is_gst_inclusive INTEGER DEFAULT 1);











-- Table: customers
CREATE TABLE customers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  phone TEXT UNIQUE,
  balance_due INTEGER DEFAULT 0, -- In Paise, Positive = they owe us, Negative = advance
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, address TEXT, email TEXT);











-- Table: bills
CREATE TABLE bills (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  bill_number TEXT UNIQUE NOT NULL,
  customer_id INTEGER,
  subtotal INTEGER NOT NULL CHECK(subtotal >= 0),          -- In Paise
  gst_total INTEGER NOT NULL CHECK(gst_total >= 0),        -- In Paise
  discount_amount INTEGER NOT NULL DEFAULT 0 CHECK(discount_amount >= 0), -- In Paise
  grand_total INTEGER NOT NULL CHECK(grand_total >= 0),    -- In Paise
  payment_mode TEXT NOT NULL CHECK(payment_mode IN ('cash', 'upi', 'mixed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL
);















































































































-- Table: bill_items
CREATE TABLE bill_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  bill_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  product_name_snapshot TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK(quantity > 0),
  unit_price INTEGER NOT NULL CHECK(unit_price >= 0),      -- In Paise
  gst_percent INTEGER NOT NULL CHECK(gst_percent >= 0),    -- Basis points
  line_total INTEGER NOT NULL CHECK(line_total >= 0),      -- In Paise
  FOREIGN KEY (bill_id) REFERENCES bills(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT
);



























































































































































































































































































































































































































































































-- Table: inventory_logs
CREATE TABLE inventory_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  product_id INTEGER NOT NULL,
  change_qty INTEGER NOT NULL,
  reason TEXT NOT NULL CHECK(reason IN ('SALE', 'MANUAL', 'ADJUSTMENT')),
  reference_id INTEGER, -- Bill ID or other reference
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);





























































































































































































































































































































































































































































































































































































































-- Table: license
CREATE TABLE license (
  id INTEGER PRIMARY KEY CHECK (id = 1), -- Singleton row
  license_key TEXT NOT NULL,
  activated_on TEXT NOT NULL DEFAULT (datetime('now')),
  expires_on TEXT NOT NULL,
  device_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, trial_started_on TEXT, is_trial INTEGER NOT NULL DEFAULT 1);


-- Table: app_config
CREATE TABLE app_config (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  shop_name TEXT NOT NULL DEFAULT 'SmartKhata Shop',
  owner_name TEXT,
  address TEXT,
  phone TEXT,
  gst_number TEXT,
  printer_name TEXT,
  paper_size TEXT CHECK(paper_size IN ('58mm', '80mm')) DEFAULT '58mm',
  gst_enabled INTEGER DEFAULT 1 CHECK(gst_enabled IN (0, 1)),
  round_off_enabled INTEGER DEFAULT 1 CHECK(round_off_enabled IN (0, 1)),
  updated_at TEXT DEFAULT (datetime('now'))
, gst_percentage INTEGER DEFAULT 5 CHECK(gst_percentage IN (5, 12, 18)), show_logo INTEGER DEFAULT 0, show_customer_details INTEGER DEFAULT 1, footer_message TEXT DEFAULT 'Thank you! Visit Again', print_copies INTEGER DEFAULT 1, auto_print INTEGER DEFAULT 1, billing_only INTEGER DEFAULT 0, customers_enabled INTEGER DEFAULT 1, gst_exclusive_mode INTEGER DEFAULT 0);


-- Table: customer_ledger
CREATE TABLE customer_ledger (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_id INTEGER NOT NULL,
  amount INTEGER NOT NULL,                             -- In Paise (absolute amount)
  type TEXT NOT NULL CHECK(type IN ('SALE', 'PAYMENT_IN', 'PAYMENT_OUT', 'OPENING_BALANCE')),
  reference_id INTEGER,                                -- Bill ID or other reference depending on type
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
);


















































































































































CREATE INDEX idx_schema_migrations_version 
ON schema_migrations(version);
CREATE INDEX idx_schema_migrations_applied_at 
ON schema_migrations(applied_at);
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_products_sku ON products(sku);
CREATE INDEX idx_products_barcode ON products(barcode);
CREATE INDEX idx_products_is_active ON products(is_active);
CREATE INDEX idx_customers_phone ON customers(phone);
CREATE INDEX idx_customers_name ON customers(name);
CREATE INDEX idx_customers_is_active ON customers(is_active);
CREATE INDEX idx_bills_bill_number ON bills(bill_number);
CREATE INDEX idx_bills_customer_id ON bills(customer_id);
CREATE INDEX idx_bills_created_at ON bills(created_at);
CREATE INDEX idx_bill_items_bill_id ON bill_items(bill_id);
CREATE INDEX idx_bill_items_product_id ON bill_items(product_id);
CREATE INDEX idx_inventory_logs_product_id ON inventory_logs(product_id);
CREATE INDEX idx_inventory_logs_reason ON inventory_logs(reason);
CREATE INDEX idx_inventory_logs_created_at ON inventory_logs(created_at);
CREATE INDEX idx_customer_ledger_customer_id ON customer_ledger(customer_id);
CREATE INDEX idx_customer_ledger_created_at ON customer_ledger(created_at);

COMMIT;
PRAGMA foreign_keys=ON;
